R(1163,"<NYI> <TXT> speak to tyrande whisperwind",[[description="x",objectives={"x"}]])
R(1164,"Ограбить воров",[[description="Воровка! Свинья! Кената все еще жива, ее семья живет и процветает, а я страдаю. Вот уж действительно Отрекшаяся!$B$BВсю мою семью забрала чума. Все наше имение тоже разорили во время войны. И теперь она и ее мерзкие дети имели наглость похитить у меня последние ценные вещи.$B$BСами вещи мне уже не нужны. Теперь я жажду мести!$B$BУбей этих проходимцев! Ступай в усадьбу Дабири в Арати, на северо-востоке от Опорного пункта.",objectives={"Принесите головы Кенаты, Фардела и Марселя Дабири Генви Кэллоу в Подгород."}]])
R(1166,"Заботы властителя Мок'Морокка",[[description="Твоя кланяться властитель Мок'Морокк!$b$bРексар назначить меня правителем клана Каменного Молота!$b$bМоя хороший вождь! Моя бережет свой клан!$b$bБольшие драконы прилетать и жечь наш старый дом. Моя – умный огр! Моя найти здесь новый дом для свой клан. $b$bБросать старый дом так быстро, что забыть моя вещи. $gМаленький:Маленькая:r; $r, ты идти и приносить моя вещи. Идти на юг и приносить мой вкусный грог, мой табак и мой сейф. Я благодарить твоя, когда твоя сделать это. Твоя искать в Обители Пламени и в руинах Деревни Каменного Молота. Они быть там, моя уверен.",objectives={"Принесите Мок'Морокку его грог, табак и сейф на Пыльную трясину."}]])
R(1167,"Башня Алталакса",[[description="Прежде чем встретиться с Атрикусом, разумно было бы тебе посоветоваться с Балтулом. Не сомневаюсь, что он неусыпно следил за башней и может знать о недавних событиях.",objectives={"Поговорите с Балтулом Ударом Тени возле башни Алталакса."}]])
R(1168,"Армия Черного дракона",[[description="Мок'Морокк получил власть от Рексара. Но он больше любил власть, чем огров.$B$BЧерные драконы убили много огров. Убили жену Тхарга. Мок'Моррокк велел нам бежать. Заставил прийти сюда.$B$BОгры должны биться. Ограм плохо бегать. Мок'Морокк думает только о Мок'Морокке.$B$BМой дом в руинах Деревни Каменного Молота. Мне нравится там на юге. Здесь не наш дом.$B$BПомоги ограм победить войско черного дракона. Мы хотим отомстить. Мы хотим домой.",objectives={"Убейте для Тхарга из Деревни Гиблотопь 15 Огнегривых Разведчиков, 10 Огнегривых Пеплохвостов и 5 Огнегривых чешуйчатых губителей."}]])
R(1169,"Корни угрозы",[[description="Пока этот трусливый глупец Мок'Морокк упивается властью, а Тхарг борется с тоской и жаждой мести и оспаривает у него власть над кланом, – я, кажется, единственный, кто хочет установить источник бед, обрушившихся на нас.$B$BПочему ты так озадаченно смотришь на меня, $n? $gДумал:Думала;, я буду говорить как неотесанный чурбан только потому, что я – огр?$b$bНо к делу. Принеси мне сердца и языки дракончиков, только что вылупившихся из яиц, и я найду корни этого зла.",objectives={"Принесите Драз'Зилбу в Деревню Гиблотопь 15 огненных языков и 15 пылающих сердец."}]])
R(1170,"Выводок Ониксии",[[description="Деревня Каменный Молот была захвачена выводком Ониксии. Но почему дочь великого дракона Смертокрыла вторглась в наши земли? Вот что тревожнее всего!$B$BНеужели только для того, чтобы уничтожить небольшое поселение огров?$B$BПредупреди Мок'Морокка. Нельзя сидеть сложа руки!",objectives={"Поговорите с властителем Мок'Морокком в Деревне Гиблотопь."}]])
R(1171,"Выводок Ониксии",[[description="Твоя уходить. Твоя идти и сказать Драз'Зилбу, мы оставаться здесь. Здесь нет никакой черный дракон.",objectives={"Поговорите с Драз'Зилбом в Деревне Гиблотопь."}]])
R(1172,"Выводок Ониксии",[[description="Выводок Ониксии расползся по всей Земле Драконов. Нельзя допустить, чтобы и остальные ее отродья вылупились на свет!$b$bПоспеши в Драконьи топи на юге Пылевых топей. Наверняка она устроила там свое логово. Найди яйца злой драконихи и уничтожь их!$b$bМы никогда не вернем себе деревню Каменного Молота, если вокруг будут продолжать плодиться драконы.$b$bА что касается Мок'Морокка... касательно этого червя у меня есть особые планы.",objectives={"Драз'Зилб из Деревни Гиблотопь хочет, чтобы вы уничтожили 5 яиц Ониксии."}]])
R(1173,"Вызов властителю Мок'Морокку",[[description="Ты осмеливаешься вызвать на поединок властителя Мок'Морокка?$b$bХа!$b$bМеня хочет сокрушить $Gжалкий:жалкая:r; $r!$B$BПриготовишься к трепке – скажи мне.",objectives={"Победите Мок'Морокка и сообщите об этом Драз'Зилбу в Деревне Гиблотопь."}]])
R(1174,"Gnomes Win!")
R(1175,"Помехи на трассе",[[description="После того как гоблинский болид \"Красный Гром\" столкнулся с василиском, Кронкрайдер нанял меня присматривать за трассой. Не знаю, что жрут местные животные, но они вырастают просто огромными, и нужно постоянно отпугивать их, чтобы они не забредали на трек во время гонки.$B$BЗнаете, что? Если желаете немного заработать, ступайте и избавьте нас от нескольких василисков.",objectives={"Убейте 10 просоленных василисков, 10 просоленных хрусталисков  и 6 просоленных взорней, после чего вернитесь к директору трассы Зерину на Мерцающую равнину."}]])
R(1176,"Уменьшение веса",[[description="На гонках имеет значение абсолютно все! Будь то малейшее изменение мощности, небольшое ослабление колец натяжения или уменьшение веса болида – любую мелочь надо принимать в расчет.$B$BМы используем в своих болидах кости стервятников – они очень крепкие и легкие. К тому же их очень легко найти. Уж чего-чего – а стервятников на Мерцающих равнинах хватает.$B$BПринеси мне немного костей, и я хорошо заплачу тебе.",objectives={"Добудьте 10 полых костей падальщика для Поззика с Мерцающей равнины."}]])
R(1177,"Моя голодный!",[[description="Моя – большой огр. $B$BМоя голодный.$B$BТвоя идти ловить рыба. Твоя принести Дробу еда.$B$BТвоя кормить Дроб, или Дроб есть твоя.",objectives={"Принесите дробильщику Грязноногу, живущему на севере Пыльной Трясины, 12 голов мурлоков из клана Болотного Плавника."}]])
R(1178,"Гоблинская поддержка",[[description="Наша гоночная команда – это гордость всей расы гоблинов! Вы удивитесь, узнав, что за личности в той или иной мере покровительствуют нашей команде.$B$BЗнаете Газлоу? Он собирает для нас детали по всему миру, а однажды даже разработал для нас новые костюмы!$B$BНесколько недель назад он пообещал прислать новый топливный регулятор, но посылка пока не пришла. Странно, обычно Газлоу держит свое слово... Может, вы не прочь съездить в Кабестан и спросить у него? Я бы не настаивал, но эти гномы нас догоняют!",objectives={"Поговорите с Газлоу в Кабестане."}]])
R(1179,"Братья Латунный Болт",[[description="Вы когда-нибудь слышали о Мерцающей равнине? Это огромное соляное плато в Калимдоре, южнее каньона Тысяча Игл. Это отличное место для гонок, потому что поверхность там совершенно... ну... равнинная!$B$BТам живет парочка гномов – мои друзья, они строят новый болид, и говорят, он жуть какой быстрый! Настолько быстрый, что их пилоты то и дело разбиваются и калечатся...$B$BОни заказали у меня несколько защитных шлемов, но у меня дела, и я не могу их отвезти.$B$BМожет быть, вы мне поможете?",objectives={"Принесите ящик с защитными шлемами Виззлу Медноштифу на Мерцающую равнину."}]])
R(1180,"Гоблинская поддержка",[[description="Вернемся к делу. Я обещал Поззику привезти новый топливный регулятор, но так и не получил его. Ревилгаз из Пиратской бухты сказал, что выслал его, но, похоже, он куда-то улетучился.$b$bКоли так, ничего не попишешь, но по меньшей мере мы можем выяснить, отправляли его или нет.$B$BПоговори с управляющим пристанью Подгребаем по ту сторону моря, пусть заглянет в свои записи.",objectives={"Поговорите с хозяином причала Лозгилем в Пиратской бухте."}]])
R(1181,"Гоблинская поддержка",[[description="Боюсь, тут я помочь уже не в силах, $n. Если ты хочешь узнать подробности, поговори с самим бароном. Никто не знает дела Ревилгаза лучше самого Ревилгаза.$B$BОн сейчас на верхнем этаже таверны на другой стороне залива.",objectives={"Поговорите с бароном Ревилгазом в Пиратской бухте."}]])
R(1182,"Гоблинская поддержка",[[description="Видишь ли, резаки Торговой Компании возле озера Назферити (в северной части Тернистой долины) оборудовали новой моделью топливного регулятора. Я подумал, что Поззик мог бы воспользоваться им, узнай мы, как он устроен. К сожалению, Коззл, тамошний штейгер, оказался несколько умнее, чем я полагал.$B$BМожет быть, тебе больше повезет, и удастся получить чертежи. Я знаю, что он хранит их в доме, но скорее всего под замком.",objectives={"Принесите чертежи топливного регулятора барону Ревилгазу из Пиратской бухты."}]])
R(1183,"Гоблинская поддержка",[[description="Все должно быть готово. Передай Поззику мои наилучшие пожелания и скажи, что если ему что понадобится, стоит только попросить. Буду ждать вестей о его новых рекордах!",objectives={"Отнесите чертежи топливного регулятора Поззику на Мерцающую равнину."}]])
R(1184,"Части роя",[[description="Вернитесь к Белгрому в Оргриммар и скажите, что Моктар в Тысяче Игл сделает все, что от него требуется. А еще скажите, что я постоянно учусь и набираюсь знаний. Он будет рад это услышать.",objectives={"Вернитесь к Белгрому Каменной Булаве в Оргриммар."}]])
R(1185,"А под хитином было...")
R(1186,"Восемнадцатый пилот",[[description="Мне сейчас нужно приспособить этот новый регулятор топлива на один из наших болидов, но если вы хотите еще немного помочь нашей команде, поговорите с Раззериком. Это наш пилот, – гм, наш восемнадцатый пилот, если точнее, – и он тоже любит вносить в болид всяческие усовершенствования.$B$BОн, правда, малость двинутый, так что не удивляйтесь, если что.",objectives={"Поговорите с Раззериком на Мерцающей равнине."}]])
R(1187,"Настройки Раззерика",[[description="Поззик – отличный механик, это я знаю, но он боится просто прибавить мощности и вырваться вперед! А вот я не боюсь.$B$BПосле того как он закончит работать с болидом, я внесу кое-какие изменения от себя: немного ослаблю ограничители, сниму кое-какие детальки с корпуса и добавлю побольше топлива!$B$BЯ заказал сефориевый ускоритель у Шрива. Он работает в Гизмориуме, в Прибамбасске, но дирижабль, на котором летел мой ускоритель, разбился в Пылевых топях! А мне он нужен, как воздух!",objectives={"Найдите сефориевый ускоритель для Раззерика на Мерцающей равнине."}]])
R(1188,"Безопасность превыше всего",[[description="Постойте-ка, что это? Шрив оставил включенным режим безопасности. Но это же ограничит мощность, которую я смогу выжать из этого ускорителя! Говорил же я ему, чтобы отключил! Плохо, плохо.$B$BВам придется отнести это в Гизмориум Прибамбасска и заставить Шрива все отключить!",objectives={"Отнесите сефориевый ускоритель Шриву в Прибамбасск."}]])
R(1189,"Безопасность превыше всего",[[description="Вот, я сделал то, что просил Раззерик. Но скажите ему, чтобы он действовал как можно осторожнее: если он допустит хотя бы малейшую ошибку, болид не покатится вперед, а превратится в кучку пепла на треке.$B$BА нам бы совсем не хотелось искать потом девятнадцатого по счету пилота!",objectives={"Верните модифицированный сефориевый ускоритель Раззерику на Мерцающую равнину."}]])
R(1190,"Только вперед",[[description="Братья Медноштиф изобрели новый материал для изготовления машин – это единственное разумное объяснение. Их машины ездят быстрее прежнего, но их внешний вид и все остальные параметры ничуть не изменились.$B$BМы точно знаем, что Риззл Медноштиф никогда не расстается с чертежами своего изобретения.$B$BЯ скажу Замеку, чтобы устроил диверсию, – тогда ты сможешь выкрасть планы.",objectives={"Дождитесь, пока Замек устроит диверсию, украдите чертежи Риззла и отнестие их Поззику."}]])
R(1191,"Помеха Замека")
R(1192,"Индарилиевая руда")
R(1193,"Сломанная западня")
R(1194,"Чертежи Риззла",[[description="В чертежах Риззла описывается процесс переработки индарилиевой руды. Из его каракулей можно понять, что эта руда добывается в недрах Ульдамана в Бесплодных землях.$B$BОстальные записи посвящены теплопроводным свойствам индарилия.$B$BПачка бумаг придавлена каким-то камнем – скорее всего, это и есть необработанная индарилиевая руда.",objectives={"Отнесите образец индарилиевой руды Поззику на Мерцающую равнину."}]])
R(1195,"Священное пламя",[[description="Кентавры племени Галак в Тысяче Игл хранят один предмет, сохранившийся еще со времен сотворения кентавров.$B$BНам бы хотелось его получить, но для этого нужен фиал воды из одного из лунных колодцев ночных эльфов.$B$BЧтобы набрать воды, тебе надо сначала добыть один из фиалов дриад, что живут близ Приюта в Ночных Лесах в сердце Ясеневого леса. Лунный колодец есть у западного берега реки Фалфаррен, к югу от главной дороги, у которой ты сможешь наполнить фиал.",objectives={"Принесите наполненный гравированный фиал Зангену Каменному Копыту в Громовой Утес."}]])
R(1196,"Священное пламя",[[description="Отнеси наполненный фиал Рау Скальному Бегуну на Заставу Вольного Ветра на юго-востоке Тысячи Игл. Туда ты можешь добраться на Великом подъемнике, что возле южного обрыва Степей.$B$BНе удивлюсь, если ты и в дальнейшем будешь нам помогать.",objectives={"Доставьте наполненный гравированный фиал Рау Скальному Бегуну на Заставу Вольного Ветра."}]])
R(1197,"Священное пламя",[[description="Водой, которую ты $принес:принесла;, можно будет затушить пламя, охраняющее реликвию кентавров. Однако оно погаснет лишь ненадолго, так что тебе придется поспешить.$B$BУтес Треснувшего Копыта – крепость кентавров – находится к северу отсюда. Огонь горит в Оплоте Треснувшего Копыта – самой охраняемой части утеса.$B$BБудь $gосторожен:осторожна; – кентавров из племени Галак очень много, и они вряд ли легко расстанутся с тем, что представляет для них большую ценность.",objectives={"Принестите раздвоенное копыто Рау Скальному Бегуну на Заставу Вольного Ветра."}]])
R(1198,"В поисках Талрида",[[description="В нынешние дни много слухов ходит о союзе Сумеречного Молота и наг в Непроглядной Пучине на побережье Ясеневого леса.$b$bЯ должен собрать как можно больше сведений для Серебряного Рассвета, что бы мы могли понять, где и когда нужна наша помощь.$b$bУже много недель прошло, как я отправил разведчика выяснить, что происходит в Непроглядной Пучине. Страж Талрид из ордена Серебряного Рассвета до сих пор не вернулся.$b$bДругие мои разведчики заняты насущными делами.$b$bПомоги мне найти Талрида, $n.",objectives={"Найдите стража Талрида из ордена Серебряного Рассвета в Непроглядной Пучине."}]])
R(1199,"Наступление сумерек",[[description="Черпая силу из старинных обрядов, посвященных Древним Богам Хаоса, Сумеречный Молот пытается вернуть своих темных покровителей и распространить смерть и ужас по всему миру.$B$BМы думаем, что Сумеречный Молот в союзе с нагами, и теперь они накапливают силы в Непроглядной Пучине на побережье Ясеневого леса.$B$BЧто бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться.$B$BОбъяви же войну Молоту и вернись с доказательствами своих подвигов! Твои труды будут достойно вознаграждены.",objectives={"Принесите 10 подвесок Сумерек стражу Менадосу из ордена Серебряного Рассвета в Дарнасс."}]])
R(1200,"Злодейство в Непроглядной Пучине",[[description="Силы оставили меня. Мне необходима твоя помощь!$B$BВ давние времена на этом месте был храм Элуны. К несчастью, он был разрушен, когда порча Древнего Бога просочилась из-под земли и осквернила священный Лунный колодец.$B$BАку'май, слуга Древнего Бога, поднялся из глубин.$B$BКультисты Сумеречного Молота объединились с нагами в борьбе за эти земли. Культисты, ведомые Келрисом, приносят Аку'май невинные жертвы.$B$BУбей Келриса и принеси его голову Сельгорму в Дарнасс, $N.",objectives={"Принесите голову Повелителя сумрака Келриса Рассветному дозорному Селгорму в Дарнасс."}]])
R(1201,"Тераморские шпионы",[[description="Орда с Альянсом сейчас находятся в состоянии шаткого перемирия. Тайные операции предпринимаются обеими сторонами, и наша обязанность – убедиться что Орда выйдет из них победителем!$b$bСейчас у нас есть шанс это сделать.$b$bАгенты Альянса заняли позицию к востоку от Деревни Гиблотопь. Они следят за деревней и докладывают о наших действиях в районе Терамора. Мы не станем этого терпеть.$b$bТвоя задача выследить этих шпионов и убить их. Этим мы ясно дадим понять их начальству, что не допустим шпионить у себя под носом.",objectives={"Убейте 9 тераморских шпионов, потом вернитесь к Назиру Кровавому Копью в деревню Гиблотопь."}]])
R(1202,"Доки Терамора",[[description="$N? Мы послылали двоих разведчиков украсть бумаги с корабля в одном из тераморских доков. Они добыли их, но были обнаружены, и им пришлось выбросить добычу в море.$b$bОдному из них удалось сбежать, но поднять документы со дна он не смог. Теперь я поручаю эту задачу тебе.$b$bБумаги лежат в сундучке, на дне моря возле тераморских доков. Найди их, $N, и принеси мне.",objectives={"Принесите документы капитана Назиру Кровавому Копью в Деревню Гиблотопь."}]])
R(1203,"Ярлу нужен клинок",[[description="Мне предстоит жестокая рубка. С кем, я тебе сказать не могу, но вот то, что мне для этого просто необходим добрый клинок, это к гадалке не ходи.  Некоторые называют его палашом лунной стали, а я зову пляшущий клинок.$b$bПоможешь мне, а? Может, где в городе найдешь, а может, кузнец какой согласится его сделать.$b$bГлавное, поторопись, то что я собираюсь рубить, ждать не станет...",objectives={"Принесите палаш лунной стаи Ярлу в Пылевые Топи."}]])
R(1204,"Суп из илистой черепахи с жучками",[[description="Я тут работаю над новым блюдом, оно будет называться \"Суп из илистой черепахи с жучками\". Мне все еще не хватает основных ингридиентов, но я не уверен, что перенесу еще одну прогулку по Пылевых топях. $N, ты не окажешь мне услугу? Прежде всего, мне нужны языки илистых черепах. Они водятся на побережье, в основном вокруг залива.$B$BНо мне не всякие языки сгодятся – я слышал, что у некоторых из этих черепах языки раздвоены. $B$BВот они-то и обладают тем непередаваемым вкусом, которым я хочу порадовать своих клиентов.",objectives={"Принесите 8 раздвоенных языков илистых черепах Моргану Штерну в Терамор."}]])
R(1205,"Зыбун",[[description="Зыбун – старый кроколиск из Пылевых топей. Ему давно уже пора сдохнуть.$B$BСкрипя старыми костями он волочет свою огромную тушу по болоту. Хотя он все еще движется с силой и скоростью молодого животного, его неугасимый пламенный дух уже износил свое дряхлое тело.$B$BТы $Gдолжен:должна; освободить его от этой боли, $N. Дай ему покой.",objectives={"Принесите зуб кроколиска Зыбуна Мелору в Громовой Утес."}]])
R(1206,"Ярлу нужны глаза",[[description="Глазной сок очень вкусный, жаль только что большинство живых существ имеет всего по два глаза.$B$BНо вот у пауков их уже больше, гораздо больше. А сок из глаз пауков Мглистой пещеры обладает особенным мягким вкусом. Целехонькие паучьи глазки... прям уже чую их на языке.$B$BЭти пауки водятся к пещере к западу отсюда. Вот как ты думаешь, это пауки были названы по своей пещере или наоборот?",objectives={"Принесите 40 целых глаз пауков Мглистой пещеры Ярлу \"Болотному Глазу\" в сторожку \"Болотный Огонек\"."}]])
R(1218,"Ароматные специи",[[description="Люблю болотную кухню. Жареные лягушачьи лапки и все такое...$b$bИ чтобы готовить, мне нужны специи. Ароматные специи. Тогда я смогу сделать славное жаркое, да и тебя угостить$b$bТы как насчет тушеной лягушатинки?",objectives={"Принесите 3 порции ароматных специй Ярлу \"Болотному Глазу\" в Пыльную трясину."}]])
R(1219,"Орочье донесение",[[description="Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку. А в трубке находился заляпаный грязью пергамент. $B$BДонесение написано на орочьем... И по виду важное...",objectives={"Доставьте орочье донесение тераморскому лейтенанту."}]])
R(1220,"Капитан Ваймс",[[description="Капитан Ваймс должен увидеть найденное тобой орочье донесение, $N. Он знает орочий язык, лучше чем кто либо из нас, и он должен быть осведомлен о том, что вблизи Терамора рыщут шпионы Орды.$B$BТы найдешь капитана в казармах в северо-восточной части острова Терамор.",objectives={"Принесите шпионское донесение капитану Гаррану Ваймсу."}]])
R(1221,"Корни Синелиста",[[description="Корень синелиста – признанный деликатес в любом уголке мира! Но растет он только здесь, в Пустошах, глубоко под землей в Лабиринтах Иглошкурых.$B$BК тому же клубни так сложно найти, если не знать точно где искать! Поэтому я специально надрессировал этих шмыгуносов, чтобы они находили корни под землей. Обоняние у них просто невероятное – они чуют корни с пятидесяти шагов!$B$BЗадачка, конечно, непростая, но если принесешь мне корней, я хорошо заплачу.",objectives={"Возьмите ящик с дырками.$BВозьмите палочку-погонялочку для шмыгуносов.$BВозьмите справочник по шмыгуносам. $B$BВ Лабиринтах Иглошкурых выпустите шмыгуноса и воспользуйтесь стеком, чтобы он начал искать корни. $B$BПринесите 6 корней синелиста, стек и ящик с дырками Мебоку Миззриксу в Кабестан."}]])
R(1222,"Спасение Вонючки",[[description="Ура! Наконец-то нашелся кто-то, кто не хочет меня съесть!$B$BНе могу отбиться от тутошнего зверья, а ты, $gпарень:подруга;, как раз мне в этом и поможешь.$B$BПовар Морган Штерн составляет рецепт нового блюда, и он послал меня сюда на поиски листьев болотного боба. Он, похоже, думает, что они вкусные.$B$BКак бы то ни было, пока я искал эти самые листья... меня окружили! Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать эти бобы!",objectives={"Сопроводите \"Вонючку\" Игнаца, затем пообщайтесь с Морганом Штерном в Тераморе."}]])
R(1238,"Потерянный рапорт",[[description="Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку. А в трубке находился заляпаный грязью пергамент. $B$BЭто донесение шпиона, который провел многие недели в Тераморе.$B$BРасшифровав его, мы выяснили, что это донесение должно быть доставлено командиру орков-разведчиков в Деревню Гиблотопь.",objectives={"Отнесите донесение шпиона Назиру Кровавому Копью в Деревню Гиблотопь."}]])
R(1239,"Отрубленная Голова",[[description="Стоило копнуть чуть глубже, и из земли показалась отрубленная голова орка. На его лице застыл оскал, а в темных глазах – вызов.",objectives={"Принесите голову строптивого орка Назиру Кровавому Копью в Деревню Гиблотопь."}]])
R(1240,"Тролль-знахарь",[[description="Мы должны выяснить обстоятельства смерти Марга! И единственный способ это сделать, $N, – воспользоваться магией троллей. $B$BОтнеси голову Марга Кин'вилаю в лагерь Гром'гол в Тернистой долине.$B$BКин'вилай – самый могущественный из знахарей Черного Копья, если кто-то и сможет вызвать дух Ночного Соглядатая – то это он.",objectives={"Принесите голову строптивого орка Кин'вилаю в лагерь Гром'гол в Тернистой долине."}]])
R(1241,"Пропавший дипломат",[[description="Некоторое время назад один из наших дипломатов был отправлен в Терамор для встречи с Джайной Праудмур. Он не вернулся.$B$BЯ подозреваю, что к этому приложило руку Братство Справедливости, но уверенности у меня пока что нет. Пока что нам удается скрывать факт исчезновения дипломата, но так продолжаться не может.$B$BАгенты королевской службы рыщут по городам, но я хочу задействовать и свои связи.$B$BВ Аллее Героев вы найдете моего старого друга, его зовут Йорген. Передайте ему эту записку и во всем его слушайтесь.",objectives={"Найдите Йоргена в Штормграде."}]])
R(1242,"Пропавший дипломат",[[description="Возьмите записку для Иллинга Триаса. Ничего ему не рассказывайте, просто ведите себя вежливо и дождитесь ответа; не волнуйтесь, Триас ответит.$B$BЕще раз напоминаю вам, $N: дело серьезное, так что держите рот на замке.$B$BТриаса вы найдете в его магазине в Торговом квартале; магазин называется \"Сыры Триаса\". Удачи!",objectives={"Доставьте запечатанную записку Йоргена Иллингу Триасу в Штормград."}]])
R(1243,"Пропавший дипломат",[[description="Йорген, ах ты старый мерзавец... Ну и что со всем этим делать?$B$BЛадно, я разберусь... Да чтоб ему в Круговерть Пустоты угодить раньше времени!$B$BНу что, $N, займемся делом? Я задействую все свои контакты, но вам придется побегать.$B$BОтправляйтесь в поселение Темнолесье, которое находится в Сумеречном лесу, и найдите там дозорного Бакуса; он обычно патрулирует северную дорогу за городской стеной. Просто скажите ему, что Братство Справедливости опять зашевелилось, а вы присматриваете за ним по моей просьбе – и он вам поможет, чем сможет.",objectives={"Отнесите запечатанное письмо дозорному Бакусу в Сумеречный лес."}]])
R(1244,"Пропавший дипломат",[[description="Опять братство?! Они вечно что-то вытворяют; даже если они затихли, мы считаем это недвусмысленной угрозой.$B$BКстати, сейчас я вспомнил, что последнюю пару недель их агенты так и кишат вокруг участка Эддла. Это подозрительно – должно быть, назревает какая-то крупная заварушка.$B$BНе хотите порыскать там и установить, в чем же дело?$B$BФерма находится к югу от дороги из Западного Края как раз на входе в Сумеречный лес.",objectives={"Найдите декларацию Братства Справедливости и верните ее дозорному Бакусу в Сумеречном лесу."}]])
R(1245,"Пропавший дипломат",[[description="О-ох, для обычной попытки ввести в заблуждение это слишком сложно. Отнесите этот документ Триасу, пусть поразмыслит над ним. И никому больше об этом не говорите. Кажется, это дело ни мне, ни ему не по плечу. Ну, посмотрим...$B$BИ, пожалуйста, $N, никому не говорите, что я вам помог. Если мое начальство поймет, что я о чем-то узнал и не поделился с ними, они могут меня запросто повесить.",objectives={"Отнесите декларацию Братства Справедливости Иллингу Триасу в Штормград."}]])
R(1246,"Пропавший дипломат",[[description="Вот что я об этом думаю... Дашель... Какой-то Дашель... Как его фамилия? Кулак! Дашель Каменный Кулак! В некоторых кругах его зовут просто Кулак, наверняка потому, что он не дурак подраться...$B$BЕго можно найти в Старом городе, прямо в центре. Поговорите с ним. Если понадобится, используйте меч или любой подручный тяжелый предмет, чтобы урезонить его, и не сомневайтесь. Если он так завязан в заговоре, как можно заключить по этим бумагам, то не расстанется с информацией по доброй воле...",objectives={"Поговорите с Дашелем Каменным Кулаком в Штормграде."}]])
R(1247,"Пропавший дипломат",[[description="Ну... м-м... да... Я кое-что знаю о встрече на участке Эддла. Она произошла несколько недель назад. Меня туда не приглашали, мое участие закончилось с провалом плана А, проклятие этим окаянным приключенцам...$B$BПарень, с которым связан план Б, пришел из Менетила. Его зовут Пронырой. Это все, что мне удалось узнать из запасного плана.",objectives={"Поговорите с Иллингом Триасом в Штормграде."}]])
R(1248,"Пропавший дипломат",[[description="Один из моих знакомых переехал в Болотину, в портовый город Менетил. Думаю, что он поможет вам, если вы передадите ему привет и скажете, что работаете на меня. Зовут его Михаил; перед отъездом он говорил, что хочет стать барменом.$B$BПоговорите с ним, найдите этого Проныру и попробуйте разузнать еще что-нибудь насчет похищенного дипломата. Мы должны узнать, где его держат или хотя бы имя похищенного. Увы, в декларации ничего не говорится о том, что похитители собираются сделать с пленником после захвата.",objectives={"Поговорите с Михаилом из Болотины."}]])
R(1249,"Пропавший дипломат",[[description="Значит, вас послал Эллинг? О, это повод десятикратно умножить мое гостеприимство! Просите всего, чего пожелаете, постараюсь выполнить любую вашу просьбу!$B$BХм-м, Проныра, говорите? Не скажу, что мне знакомо это имя, но постараюсь что-нибудь разведать...$B$B$N, не оборачивайтесь прямо сейчас, но вон тот господин около двери слишком внимательно смотрит на нас и прислушивается к нашему разговору. На вашем месте я бы попробовал изловить его прежде, чем он уйдет отсюда.",objectives={"Перехватите Яна Проныру до его ухода и вернитесь к Михаилу."}]])
R(1250,"Пропавший дипломат",[[description="Братство Справедливости не столько мне платит, чтобы за них умирать. Они похитили короля. Да, настоящего короля Штормграда, а не какого-то там дипломата. Он направлялся в Терамор, чтобы побеседовать с Джайной Праудмур, это большая тайна и дело тоже нешуточное. Но тут встряло братство, у них был свой осведомитель.$B$BВ мои задачи входило только взять их человека на борт королевского корабля, когда он стоял у пристани. Парня звали Хендел, клянусь, это все, что я знаю!",objectives={"Поговорите с Михаилом в Болотине."}]])
R(1251,"Черный Щит",[[description="Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остове камина – только это и осталось от таверны \"Последний привал\".$B$BЩит можно снять.",objectives={"Прнинесите почерневший железный щит Крогу в Деревню Гиблотопь."}]])
R(1252,"Лейтенант Павал Рит",[[description="Солнечный зайчик блеснул в глаза из-под обломков. Вы достаете из-под мусора бляху с золотым якорем на белой эмали – символом Терамора.$B$BПод якорем выбито имя владельца: \"Лейтенант Павал Рит\".",objectives={"Принесите бляху Рита капитану Гаррану Ваймсу в Терамор."}]])
R(1253,"Черный Щит",[[description="Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остатках камина – только это и осталось от таверны \"Последний привал\".$B$BЩит можно снять.",objectives={"Принесите почерневший железный щит капитану Гаррану Ваймсу в Терамор."}]])
R(1258,"…и жуки.",[[description="Еще один компонент моего нового рецепта – клешни гигантского краба. К сожалению, те которые водятся в Пыльной трясине, – грязнокрабы, не годятся... Зато те, что живут на Болоте Печали, – в самый раз!$b$bОболочка клешни – важный элемент украшения блюда, поэтому они мне нужны целые и непоцарапанные. К сожалению, у краба всего две клешни, а то и одна, а мне для моих кулинарных экспериментов их нужно гораздо больше. Так что насчет небольшой прогулки, $N?",objectives={"Принесите 12 безупречных крабьих клешней Моргану Штерну в Терамор."}]])
R(1259,"Лейтенант Павал Рит",[[description="Лейтенант Павал Рит? Не припоминаю такого имени. Лучше всего вам будет поговорить с адъютантом Тезораном. У него хранятся все записи о тераморских стражниках – от их имен до предпочитаемого вооружения.$B$BУж он-то расскажет вам об этом Павале Рите.",objectives={"Поговорите о Рите с адъютантом Тезораном в Тераморе."}]])
R(1260,"Морган Штерн",[[description="Я составляю новое меню для ресторана. Сельская кухня с болотным душком. Думаю, посетителям \"Синего отшельника\" понравится!$b$bЯ послал своего племянника Моргана в Терамор, город на краю Пылевых топей. Там он собирает местные кулинарные рецепты, и мне хотелось бы знать, как его успехи.$b$bДолог путь до Терамора, и для меня тяжеловат. Но я думаю, что $Gтакой молодой:такая молодая:c; $c с радостью ухватится за возможность совершить подобное путешествие.",objectives={"Поговорите с Морганом Штерном в Тераморе."}]])
R(1261,"Марг говорит",[[description="Ах ты, проклятый грязнокраб! Ты меня не достанешь! Ой, да я ж покойник! Видать, он все-таки достал меня.$B$BА как же моя миссия?! Ты, $n, $Gдолжен:должна; закончить ее. Я наблюдал за силами Альянса, высадившимися на берегу возле Терамора. На одном из солдат была подвеска, на которой было столько драгоценных камней, что не всякий вождь может себе позволить.$B$BТой ночью я пробрался в лагерь и украл эту подвеску. Но когда я возвращался в свой лагерь, этот проклятый грязнокраб прикончил меня!$B$B$N, ты $Gдолжен:должна; найти эту тварь и вернуть подвеску.",objectives={"Принесите изукрашенную Подвеску Назиру в Деревню Гиблотопь."}]])
R(1262,"Сообщение для Зора",[[description="Странно, что украденная Маргом была у простого солдата. Возможно ее владелец маскировался, или, что вероятнее, солдаты сами ее стащили. $B$BЧто бы там ни было, эта подвеска принадлежала лицу благородного происхождения, и мы должны найти ее хозяина, если хотим разрешить эту загадку.$B$BОтнеси эту подвеску Зору Одинокое Дерево в Оргриммар. Он хорошо разбирается в интригах Альянса и, возможно, он в курсе, если эта подвеска известна в Штормграде.",objectives={"Отнесите изукрашенную подвеску Зору Одинокому Дереву в Оргриммар."}]])
R(1263,"The Burning Inn <CHANGE TO GOSSIP>")
R(1264,"Пропавший дипломат",[[description="В начале каждого месяца стражи бухты Кул-Тираса получают жалованье и отправляются прочь из Терамора в отпуск. Многие из них приходят сюда – выпить, гульнуть, пообщаться с женщинами. Одна из таких компаний регулярно приходит в эту таверну. Мне кажется, что и этот Хендел был среди них.$B$BКомандир Самаул из Терамора может вам помочь в поисках Хендела, если тот до сих пор там. Самаул всецело верен леди Джайне, но если ты упомянешь при нем имя Эллинга, он должен стать... посговорчивее.",objectives={"Найдите командира Самаула в Пылевых топях."}]])
R(1265,"Пропавший дипломат",[[description="Хендел? Да, я его знаю, но почему вас интересуют мои солдаты?$B$BЭллинг отправил вас разыскать его? Звучит как-то странно. Эллинг не послал бы вас ко мне, если бы все было в порядке. Вы можете хранить свои секреты сколько угодно, только имейте в виду: мой долг – охранять эти земли. Если ваша деятельность может нарушить порядок, лучше сообщите заранее.$B$BДумаю, что Хендела вы найдете в первой по счету от Терамора башне. Будьте осторожны.",objectives={"Обыщите сторожевой пост, чтобы найти следы рядового Хендела."}]])
R(1266,"Пропавший дипломат",[[description="Рядовой Хендел находится к западу отсюда, в составе гвардии, охраняющей тераморских разведчиков во время отдыха. Они пытаются выяснить местоположение деревни Папоротники, базы Орды, а заодно и приглядывают за нашими границами.$B$BВы найдете его без труда, просто поищите в палатках у дороги.$B$BУ меня есть и другие дела, но я догоню вас так быстро, как смогу. При необходимости вы сможете найти меня в башне леди Праудмур.",objectives={"Найдите рядового Хендела в Пылевых топях."}]])
R(1267,"Пропавший дипломат",[[objectives={"Поговорите с леди Джайной Праудмур из Пыльной трясины."}]])
R(1268,"Подозрительные следы копыт",[[description="Цепочка следов уходит от все еще дымящегося остова таверны \"Последний привал\". В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчетливо.",objectives={"Доложите о подозрительных следах возле таверны \"Последний привал\" Крогу в Деревне Гиблотопь."}]])
R(1269,"Лейтенант Павал Рит",[[description="Солнечный зайчик блеснул в глаза из под обломков. Вы достаете из-под мусора бляху с золотым якорем на белой эмали – символом Терамора.$B$BПод якорем выбито имя владельца: \"Лейтенант Павал Рит\".",objectives={"Принесите бляху Рита Крогу в деревню Гиблотопь."}]])
R(1270,"Побег Вонючки",[[description="Ура! Наконец-то нашелся кто-то, кто не хочет меня съесть!$B$BНе могу отбиться от тутошнего зверья, а т ы, $gпарень:подруга; как раз мне в этом и поможешь. Гоблину из Кабестана по кличке Мебок Миззрикс нужны листья болотного боба для зелья или еще какой надобности, – меня это, честно говоря, не колышет: он неплохо платит, а я неплохо знаю болота, потому и впрягся.$b$bВот только не успел я еще найти эти листья, как меня уже окружили. Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать для Мебока эти листья.",objectives={"Сопроводите \"Вонючку\" Игнаца, затем пообщайтесь с Мебоком Миззриксом в Кабестане."}]])
R(1271,"Праздник в \"Голубом Отшельнике\"")
R(1273,"Допрос Рита",[[description="Это было непросто, но я все-таки нашел этот Рит. Неплохо он прятаться... Для человек. $B$BОгрон боится, что человек свихнуться, – слишком много времени на болоте, Твоя идти с Огрон и спрашивать человека все, что хотеть.",objectives={"Пойдите с Огроном и поговорите с Ритом, потом вернитесь к Крогу в Деревню Гиблотопь."}]])
R(1274,"Пропавший дипломат",[[description="Простите, $gсэр:мадам;. Епископ Делавей попросил меня разыскать любителя приключений, который мог бы помочь ему, оказав услугу весьма деликатного свойства.$B$BЕсли вы без лишнего шума проберетесь в Крепость Штормграда и обратитесь к епископу, он наверняка примет вашу помощь. Прошу вас, храните это в тайне, ибо все это дело большой важности.",objectives={"Найдите епископа Делавея в Крепости Штормграда."}]])
R(1275,"Исследование порчи",[[description="Безрассудные эльфы крови попали в западню демонической магии. Разве они не видели, что случилось с нагами и сатирами Калимдора?$B$BЯ боюсь, что эльфы крови могут претерпеть такую же трансформацию. Азерот не может позволить себе породить еще одну расу злобных монстров.$B$BЯ хотел бы изучить ствол мозга сатиров и нагов, чтобы понять, на что обрекают себя эльфы крови. И сатиров, и нагов вы найдете в Непроглядной Пучине, на побережье Ясеневого леса.$B$BПуть неблизкий, $n.",objectives={"Гершал Шепот Ночи в Аубердине хочет, чтобы вы принесли ему 8 оскверненных стволов мозга."}]])
R(1276,"Черный Щит",[[description="А, вспомнил! Мозарн – знаменитый кузнец из Громового Утеса. Я же помню, что слышал это имя прежде!$B$BЕсли мне не изменяет память, Служители Земли наградили меня оружием его работы, хорошее было оружие.$B$BВозможно, он расскажет тебе больше о щите, вышедшем из его рук.$B$BЯ не уверен, что эта информация важна, но, поскольку мы так и не знаем ничего о Рите, пренебрегать ей было бы неразумно.",objectives={"Покажите потемневший железный щит Мозарну из Громового Утеса."}]])
