R(3091,"Простая записка",[[description="Привет, $N! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставника воинов Харутта. На твоем месте я бы прочитал ее поскорее.",objectives={"Прочтите простую записку и поговорите с Харуттом Громовым Рогом в Лагере Нараче."}]])
R(3092,"Нацарапанная записка",[[description="Привет, $N! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставника охотников Ланко. На твоем месте я бы прочитал ее поскорее.",objectives={"Прочтите нацарапанную записку и поговорите с Ланко Дальнострелом на Плато Красного Облака."}]])
