R(3095,"Простой свиток",[[description="А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника воинов Даннала. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.",objectives={"Прочитайте простой свиток и поговорите с Данналом Штерном в Могильнике."}]])
R(3096,"Зашифрованный свиток",[[description="А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника разбойников Давида Триаса. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.",objectives={"Прочитайте зашифрованный свиток и поговорите с Давидом Триасом в Могильнике."}]])
R(3097,"Священный свиток",[[description="А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника жрецов Дьюстена. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.",objectives={"Прочитайте священный свиток и поговорите с темным священником Дьюстеном в церкви Могильника."}]])
R(3098,"Свиток, покрытый письменами",[[description="А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями Плети, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставницы магов Изабеллы. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.",objectives={"Прочитайте свиток, покрытый письменами, и поговорите с Изабеллой в церкви Могильника."}]])
