R(3100,"Обычное письмо",[[description="Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Ллана, местного наставника воинов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.",objectives={"Прочитайте обычное письмо и поговорите с Лланом Бишером в Аббатстве Североземья."}]])
R(3101,"Благословенное письмо",[[description="Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать брата Самуэля, местного наставника паладинов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.",objectives={"Прочитайте благословенное письмо и поговорите с братом Самуэлем в Аббатстве Североземья."}]])
R(3102,"Зашифрованное письмо",[[description="Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Джорика, одного из наших местных наставников. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.",objectives={"Прочитайте зашифрованное письмо и поговорите с Джориком Керриданом в стойлах за Аббатством Североземья."}]])
R(3103,"Святое письмо",[[description="Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Анетты, местной наставницы жрецов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.",objectives={"Прочитайте святое письмо и поговорите с жрицей Анеттой в Аббатстве Североземья."}]])
R(3104,"Символьное письмо",[[description="Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Келдена, местного наставника магов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.",objectives={"Прочитайте символьное письмо и поговорите с Кельденом Бременом в Аббатстве Североземья."}]])
R(3105,"Тайное письмо",[[description="Меня просили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем печать Друзиллы, одной из наших местных наставниц. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь, в аббатстве.",objectives={"Прочитайте тайное письмо и поговорите с Друзиллой ла Салле возле Аббатства Североземья."}]])
R(3106,"Простая руна",[[description="Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне.",objectives={"Изучите простую руну. Найдите в Холодной долине Трана Кормана и поговорите с ним."}]])
R(3107,"Священная руна",[[description="Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Бромос, наставник паладинов. Если представится случай, отыщи его в Старой Наковальне.",objectives={"Изучите священную руну. Найдите в Холодной долине Бромоса Груммнера и поговорите с ним."}]])
