R(3114,"Таинственная записка",[[description="Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Маррайк, наставник магов. Если представится случай, отыщи его в Старой Наковальне.",objectives={"Прочитайте таинственную записку. Найдите в Старой Наковальне Маррайка Нуррибита и поговорите с ним."}]])
R(3115,"Гниющая записка",[[description="Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Аламар, наставник чернокнижников. Если представится случай, отыщи его в Старой Наковальне.$B$BДа, $N, вот еще что... будь осторожнее. Таким, как ты, тут не слишком-то доверяют.",objectives={"Прочтите гниющую записку. Найдите в Старой Наковальне Аламара Мрачнна и поговорить с ним."}]])
R(3116,"Простой знак",[[description="Этот знак был передан мне посланником нашей наставницы воинов, Алайссии. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Алайссии.",objectives={"Изучите простой знак и поговорите с Алайссией в Тенистой долине."}]])
R(3117,"Выгравированный знак",[[description="Этот знак был передан мне посланником нашей наставницы охотников, Аянны. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Аянне.",objectives={"Изучите выгравированный знак и поговорите с Аянной Вечнобродкой на верхушке Альдрассила в Тенистой долине."}]])
R(3118,"Зашифрованный знак",[[description="Этот знак был передан мне посланником нашего наставника разбойников, Фрагуна. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Фрагуну.",objectives={"Прочтите зашифрованный знак и поговорите с Фрагуном Шепотом Тени в Тенистой долине."}]])
R(3119,"Благословенный знак",[[description="Этот знак был передан мне посланником нашей наставницы жрецов, Шанды. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Шанде.",objectives={"Прочтите благословенный знак и поговорите с Шандой в Альдрассиле."}]])
R(3120,"Зеленый знак",[[description="Этот знак был передан мне посланником нашего наставника друидов, Марданта. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Марданту.",objectives={"Прочтите зеленый знак и поговорите с Мардантом Крепким Дубом на древе Альдрассил в Тенистой долине."}]])
R(3121,"Странная просьба",[[description="Для начала мне понадобится помощь Нииру Огненного Клинка из Оргриммара! Он изготовил состав, который нужен мне для... ну, потом увидишь.$b$bВ общем, ступай в Оргриммар. Да, и захвати с собой вот это. Это мумифицированная голова, которую я обещал Нииру в обмен на его травки. Какой-то злосчастный дворф, с которым я повстречался в лесу... Думаю, Нииру останется доволен.$b$bИщи его в расселине Теней.",objectives={"Отнесите сушеную голову Нииру Огненному Клинку в Оргриммар."}]])
R(3122,"Возвращение к знахарю Узер'и",[[description="Вот травы, $n. Отнеси их знахарю Узер'и.$B$BИ, пожалуйста, передай ему, что сушеная голова – то, что надо.",objectives={"Отнесите знахарю Узер'и в Фералас мешочек для трав Нииру."}]])
R(3123,"Испытание сосуда",[[description="Это будет испытание – испытание созданного мною ритуала, и твоих способностей тоже. Возьми этот сосуд, $n. С его помощью ты сможешь уменьшать и помещать внутрь него разных существ.$b$bОтправляйся во Внутренние земли и отыщи существ, которых называют дикосовухами. Они некогда были питомцами богини Элуны, которую почитают ночные эльфы. Коварные и дикие совухи станут твоей первой добычей, $n. Убей 10 и с помощью сосуда уменьшения возьми их души в плен, пока они не успели ускользнуть.",objectives={"Отправляйтесь во Внутренние земли, найдите дикосовухов, убейте 10 особей и используйте сосуд уменьшения, чтобы уменьшить и пленить павших дикосовухов.$b$bОтнесите 10 уменьшенных дикосовухов знахарю Узер'и в Фералас."}]])
R(3124,"Уменьшенный гиппогриф",[[description="Ты уже $gдоказал:доказала;, что на тебя можно положиться, и ты умеешь обращаться с сосудами уменьшения. Теперь я попрошу тебя пленить другое создание.$B$BГиппогрифы в течение многих лет были верными спутниками ночных эльфов, и души их тверды и преданны.$B$BТвоя задача – убить 10 блеклоперых гиппогрифов, быстро уменьшить их и загнать в сосуды, чтобы сохранить таким образом их души. Гиппогрифов можно найти в Высокогорных дебрях, к югу отсюда.",objectives={"Убейте 10 блеклоперых гиппогрифов любого вида, затем используйте сосуд уменьшения, чтобы уменьшить и пленить их."}]])
R(3125,"Уменьшенный лесной дракончик",[[description="$n, теперь я попрошу тебя отловить существо, которое на вид кажется довольно хилым, но дух его могуч, а это – именно то, что нам надо. Лесные дракончики, о которых я говорю, были союзниками ночных эльфов. Нам надо поймать такого дракончика, чтобы Орда тоже могла воспользоваться силой его духа.$B$BУбей 8 летучих хамелеонов или радужных дракончиков, и плени их души. Эти существа водятся к западу отсюда.",objectives={"Убейте 8 летучих хамелеонов или радужных дракончиков. Используйте сосуд уменьшения, чтобы пленить павших лесных дракончиков."}]])
R(3126,"Уменьшенный древень",[[description="Следующей нашей добычей, $n, станут бродячие лесные великаны, живые деревья. Ночные эльфы считают древней своими союзниками в борьбе против Орды. Движения древней медлительны, но в качестве защитников они незаменимы!$B$BИ вскоре мы сможем использовать их мощь в своих целях.$B$BОтыщи 3 бродячих лесных древней, убей их и используй этот сосуд уменьшения, чтобы пленить их души!",objectives={"Убейте 3 бродячих лесных древней. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших древней."}]])
R(3127,"Уменьшенный горный великан",[[description="Последнее, что от тебя потребуется – это отправиться на северо-запад и отыскать основного противника.$B$BКогда Пылающий Легион явился в мир, горные великаны спустились с гор, чтобы помогать ночным эльфам. Ты без труда обнаружишь их: они огромного роста, и когда они поблизости, земля начинает дрожать под ногами.$B$BЯ жажду подчинить себе подобную мощь! Убей 7 горных великанов и используй сосуд уменьшения, чтобы пленить их могучие души!",objectives={"Убейте 7 сухопутных бродяг или скальных великанов. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших скальных великанов."}]])
R(3128,"Природные материалы",[[description="Для выполнения моего замысла мне нужны некоторые материалы... Будешь выполнять другие мои поручения – поищи заодно и то, что я тебя попрошу.$B$BВо-первых, расколотый ствол фераласского древня. Во-вторых, покрытые коркой минералы – эти можно добыть у горных великанов и волшебных драконов на западе. Кроме этого, добудь мне упругих сухожилий совухов из Внутренних земель либо гиппогрифов из Фераласа. И, наконец, мне потребуется большое количество металлических фрагментов, какие найдутся у любого из перечисленных созданий.",objectives={"Принесите 2 расколотых бревна, 6 минералов, покрытых коркой, 20 кусков упругих сухожилий и 40 металлических фрагментов знахарю Узер'и в Лагерь Мохаче."}]])
R(3129,"Оружие духа",[[description="Вселить дух животного в оружие – процесс непростой! Теперь, когда у меня есть все необходимые материалы и души пойманных тобой созданий, я могу приступить к делу. Погоди немного, я скоро вернусь.",objectives={"Подождите, пока знахарь Узер'и готовит оружие."}]])
R(3130,"Борьба с Гребнем Ненависти",[[description="В данный момент я собираюсь направить тебя к своему заместителю, Латроникусу. Он следит за боевыми приготовлениями наг. Сама же я буду продолжать осуществлять общее наблюдение. Как бы мне ни хотелось нанести им удар всеми имеющимися у нас силами, оставить крепость беззащитной перед атаками Орды – а может быть, и кого-то похуже, – не представляется разумным.$B$BКак бы то ни было, Латроникус тебя ждет. Пока что ты $gпоказал:показала; себя молодцом, $n. Продолжай в том же духе!$B$BМожешь идти.",objectives={"Явитесь к Латроникусу Лунному Копью в Крепость Оперенной Луны."}]])
R(3141,"Лорамус",[[description="Так ты хочешь вступить в сражение с демонами? Тебе лучше для начала услышать то, что я скажу.",objectives={"Послушайте, как Лорамус Многоног рассказывает свою историю."}]])
R(3161,"Газ'ридианские украшения",[[description="Я ученый, но в душе – кладоискатель!$B$BДавным-давно, когда в этих землях жили тролли, они обожествляли Газ'риллу, огромную гидру, и создали множество украшений в форме ее тела. Их вырезали из особого материала, я называю его \"газ'риллий\" в честь богини-гидры.$B$BЯ и сам ухитрился найти несколько образцов, но для исследований этого не хватает – может, ты мне еще принесешь?$B$BЯ даже создал детектор, позволяющий мигом обнаружить газ'риллий! Надень его и приступай к поискам!",objectives={"Марвон Клепальщик из Танариса поручил собрать 30 газ'рилловых украшений."}]])
R(3181,"Рог чудовища",[[description="Гигантский рог испещрен многочисленными сколами и царапинами, кроме того, из него торчит непонятный металлический предмет. $B$BОсмотрев рог более внимательно, вы понимаете, что металлический предмет есть ничто иное как обух секиры, сорванный с рукояти. На нем виднеется гравировка:$B$B\"Принадлежит горному пехотинцу Щебеночке\".$B$BКогда вы пытаетесь вытащить обух секиры из рога, он рассыпается на кусочки. $B$BОпаньки...",objectives={"Отнести гигантский рог Маргола горному пехотинцу Щебеночке."}]])
R(3182,"Доказательство собственности",[[description="Ты думаешь, я поверю этим россказням? Если бы это был настоящий рог, из него до сих пор торчал бы обух моей секиры.$B$BВот что, неси-ка свою подделку куратору Ториусу в Стальгорн. Если он признает, что твои слова – правда, он даст тебе доказательство. Принеси его мне, и я дам тебе ключ к Тлеющему ущелью.$B$BИди, иди!",objectives={"Отнесите гигантский рог Маргола куратору Ториусу в Стальгорн."}]])
R(3201,"Наконец-то!",[[description="Не может быть, чтобы Щебеночка усомнилась в подлинности рога. Между нами говоря, думаю, она просто ревнует. Я знаю, она хотела убить чудовище сама.$B$BТак вам, значит, нужно доказательство. Разумеется, вы принесли музею столь ценный дар, что я почту за честь написать для вас свидетельство. $B$B*Куратор Ториус начинает заполнять огромный документ* $B$BНу вот, можете показать его Щебеночке.",objectives={"Отнесите доказательство содеянного горному пехотинцу Щебеночке."}]])
R(3221,"Беседа с Ренферрелом",[[description="Пока вы отсутствовали, помогая нашим стражам смерти, за вами приходил аптекарь Ренферрел. Он не рассказывал мне подробностей, но хотел поговорить с вами о волчьих сердцах, что вы ему передали.",objectives={"Поговорите с аптекарем Ренферрелом в Гробнице."}]])
R(3241,"<NYI> <TXT><redux> Dreadmist Peak",[[description="Collect the totems from Dreadmist Peak, because it's icky there now and no place for shiny clean totems.",objectives={"Bring them to Tonga Runetotem."}]])
R(3261,"Джорн Заклинатель Небес",[[description="Вот и закончились наши уроки, $N. Не останавливайся на достигнутом, ступай в Лагерь Таурахо на юге и поговори с Джорном Заклинателем Небес. Он станет твоим новым учителем.",objectives={"Поговорите с Джорном Заклинателем Небес в Лагере Таурахо."}]])
R(3281,"Похищенное серебро",[[description="Ящеров-то ты $gубил:убила;, но похищенное серебро необходимо вернуть! Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров. Скорее всего они утащили похищенное серебро именно туда.$B$BОтправляйся логово мерзких тварей и поищи наше серебро. Как найдешь – сразу возвращайся ко мне.",objectives={"Принесите украденное серебро Газрогу в Перекресток."}]])
R(3301,"Муура Рунический Тотем",[[description="Одна из моих соплеменниц, Муура Рунический Тотем, отправилась в Серебряный бор на помощь нашим союзникам-нежити. Серебряный бор – больной, вымирающий лес, и Муура надеялась вдохнуть в него новую жизнь. Может быть, необычные обитатели Степей подскажут ей, как лучше выполнить задачу.$B$BВозьми образец добытых тобой панцирей и отнеси его Мууре в Серебряный бор. Она остановилась в Гробнице. При удаче, осмотрев панцирь, она придумает, как исцелить это погибающее место.",objectives={"Поговорите с Муурой Руническим Тотемом в Гробнице."}]])
R(3321,"Не ее ли ищете?",[[description="Ты много $gсделал:сделала; для Ордена, $N. Обычный искатель приключений не выдержал бы такой нагруки. Ни я, ни Гальван не сомневаемся, что ты $gстал одним:стала одной; из нас.$b$bПоэтому мне кажется, что ты заслуживаешь награды. Сущий пустяк, побрякушку. Может быть, ты знаешь о ее свойствах. Должно быть, именно из-за них ты и $gпришел:пришла; к нам.",objectives={"Дождитесь, пока Трентон закончит работу."}]])
R(3341,"Да сгинет Хладовей",[[description="В Степях есть уголок, заросший кошмарными колючками. Он называется Курганы Иглошкурых. Хотя с первого взгляда это место не показалось нам опасным, по последним сведениям все куда серьезнее…$B$BЖивущие в холмах свинобразы поддались злому влиянию Плети. Теперь их действиями руководит лич по имени Амненнар Хладоносец.$B$BУ Амненнара прямая телепатическая связь с Нер'зулом; мы должны прервать ее, $N. Да сгинет Хладовей!",objectives={"Эндрю Браунелл поручил вам убить Амненнара Хладовея и принести его череп."}]])
R(3361,"Беда беженца",[[description="Мы изгнали троггов из Гномрегана и уж было собрались праздновать победу, но тут все пошло наперекосяк! Только представь: радиация кругом, а гномы – те, кто еще жив – разбрелись по Дун Морогу...$B$BЯ так торопился, что все свои вещи бросил, да и все инструменты в придачу. Вот тролли – те не растерялись: им что радиация, что грибной дождик... Прибрали все к рукам: и сундук, и ларец, и даже ведро с винтиками не постеснялись прихватить! Все, все уволокли к себе в лагерь, куда-то к юго-западу от Старой Наковальни...$B$BПутешественник из меня никудышный, так я вот тут подумал: может, ты у них заберешь мои вещи и вернешь их мне?",objectives={"Принести в Старую Наковальню ларец Феликса, сундук Феликса и ведро с винтиками и вручить все это Феликсу."}]])
R(3362,"Долина Кактусов",[[description="Ты когда-нибудь $gбыл:была; в Долине Кактусов? Это опасное место, $N.$b$bТам такие жуткие твари, я им ни на минуту не верю! Бугристые шипокожи и терновые корнеплеты, кажется так они зовутся…$b$bТак или иначе, я хочу попасть в эту долину, но пока там столько шипокожи, ноги моей там не будет. Вот зачем ты мне $gнужен:нужна; – если выкосить часть этих тварей, я могу и решиться на поход. Что скажешь, $N? Поможешь мне?",objectives={"Тран'рек из Прибамбасска велит убить 8 бугристых шипокожев и 8 терновых корнеплетов."}]])
R(3363,"Оскверненный песнецвет")
R(3364,"Жгучая бражка",[[description="Я уже давно должен был доставить эту отличнейшую жгучую бражку в Старую Наковальню Дарнану Мехорезу, да только сначала мне нужно было завезти немного Грелину. Боюсь, к тому времени, как я доберусь до Старой Наковальни, остынет бражка-то!$B$BТы на ногу полегче моего будешь, как я погляжу; вот я и подумал... эта кружка останется горячей еще минут пять, а Дарнан вовсе не охлажденную бражку заказывал, – не пиво, чай! – так что отправляйся-ка ты в путь. Старая Наковальня – это такое поселение в скалах к северо-востоку отсюда.$B$BБлагодарю заранее... и вот еще что, $N: не забудь вернуть мою кружку!",objectives={"Отнести жгучую бражку в Старую Наковальню и передать ее Дарнану Мехорезу. Это надо сделать за пять минут, пока бражка не остыла!"}]])
R(3365,"Возвращение кружки",[[description="Ох, хорошо-то как! Все эти прохладительные напитки – полная ерунда: в морозный денек нет ничего лучше глотка горячей бражки! Даже на душе теплее становится!$B$BВот, держи, $N; сделай доброе дело, отнеси эту кружку Нори, ладно?",objectives={"Отнесите кружку хозяину – Нори по прозвищу Гордый Штрек."}]])
R(3366,"Светящийся осколок",[[description="Светящийся осколок ярко-зеленый, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство.$B$BПожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке.",objectives={"Отправляйтесь в Кабестан и выясните, какие секреты скрывает кошмарный осколок."}]])
R(3367,"Камни Сунтары",[[description="<Из груди Дориуса вырывается стон> $B$BЯ тяжело ранен, $r. Ужасно кружится голова... Думаю, у меня внутреннее кровотечение... $B$BМне нужно добраться обратно в Стальгорн. Помоги мне, $N.",objectives={"Помогите Дориусу вернуться в Стальгорн."}]])
R(3368,"Камни Сунтары",[[description="Брат! $B$BЕсли ты читаешь эти строки, меня уже нет в живых. Не знаю, кто доставил тебе письмо, но непременно поблагодари и вознагради его. $B$BТеперь о камнях: они существуют и сейчас находятся у клана Черного Железа. С помощью этих камней их главарь, Латорик Черный, удерживает моих соратников по экспедиции в плену. Лишенные рассудка, они день и ночь трудятся над созданием монстра, именуемого Обсидионом. $B$BСпаси их, брат. Это моя последняя воля. $B$BДориус.",objectives={"Доставьте опаленное письмо Ториусу в Стальгорн. Его можно найти в Зале Исследователей."}]])
R(3369,"Кошмары",[[description="Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Однако, это осколок не сна, а скорее кошмара.$B$BНе хочу тревожить тебя, $N, но лучше будет, отдать его кому-то из старших друидов, как только сможешь.$B$BХамуул Рунический Тотем с Вершины Старейшин, вот кого тебе надо найти. Отправляйся на Громовой Утес, точнее сказать не могу.",objectives={"Принесите осколок кошмара Хамуулу Руническому Тотему на Вершине Старейшин."}]])
R(3370,"Кошмары",[[description="Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Однако, это осколок не сна, а скорее кошмара.$B$BНе хочу тревожить тебя, $N, но лучше будет, отдать его кому-то из старших друидов, как только сможешь.$B$BМатренгил Медвежья Лапа из Круга Кенария, вот кого тебе надо найти. Отправляйся в Дарнасс, точнее сказать не могу.",objectives={"Принесите осколок кошмара Матренгилу Медвежьей Лапе в Дарнасс."}]])
R(3371,"Правосудие дворфов",[[description="Теперь в груди моей зияет черная дыра – там, где было когда-то сердце... Я никогда не смогу смириться с гибелью Дориуса, $N. Я сделаю все, чтобы его последняя воля была исполнена – тех, на ком его кровь, должна настигнуть суровая кара. $B$BВозвращайся в Тлеющее ущелье и исполни волю Дориуса – освободи его соратников.",objectives={"Вернитесь в Тлеющее ущелье и найдите археологов Дориуса."}]])
R(3372,"Отпусти их",[[description="Отпусти их, $r. Даже когда их тела совсем обессилеют, власть Сунтары заставляет их достичь цели любой ценой. $B$BВсе дело в алтаре Сунтары. Отправляйся на северо-запад, там, в холмах над пещерой... Сумеречный Молот хранит реликвию. Добудь ее и возложи на алтарь Сунтары.$B$B*С этими словами умирающий археолог испускает дух*.",objectives={"Найдите таинственный артефакт, охраняемый идолослужителями Сумеречного Молота в северо-западной области Тлеющего ущелья."}]])
R(3373,"Сущность Эраникуса",[[description="Вы касаетесь камня и слышите голос, звучащий в вашем сознании.$B$B\"Услышь мою мольбу, о $gсмертный:смертная;. Имя мне Эраникус из народа зеленых драконов. Мои попытки положить конец богохульным деяниям троллей закончились неудачей. Я вдохнул частицу своей души в этот кристалл. Однако я чувствую, что моя связь с Изумрудным Сном теряется, и меня поглощает хаос. Пожалуйста, помести этот кристалл с купель сущности в моем логове – пусть магия очистит мое сознание от скверны и спасет меня!\"",objectives={"Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме."}]])
R(3374,"Сущность Эраникуса",[[description="Вы приводите в действие Камень клятвы и с его помощью Итар мысленно заговаривает с вами.$B$B\"Приняв силу, заключенную в камне Клятвы, ты соглашаешься помочь мне и драконьему выводку Изеры освободить истерзанную душу Эраникуса. Первая из многих жертв, на которую придется пойти и тебе, и мне – это передать мне камень, в котором заключено то, что осталось от свободной воли Эраникуса.$B$BСделай это, $N, и дальше мы будем действовать вместе, чтобы освободить достойную многих жертв душу.\"",objectives={"Принесите камень Клятвы драконьего выводка Изеры и скованную сущность Эраникуса на Болото Печали. Там вам придется сделать выбор: помогать Драконам Изеры или нет."}]])
R(3375,"Запасной фиал",[[description="Хм... тебе нужен еще один фиал виденья? Шутишь? А куда ты $Gдел:дела; прежний?! У нас и так забот полон рот, $r. Эти фиалы на деревьях не растут! Хорошо бы, чтобы росли, я тогда пошел бы да сорвал, потому как другого-то у меня нет!$B$BА чтобы сделать тебе новый, мне нужно следующее: зелье маны, кусок угля и немного сладкого нектара. И не спрашивай зачем, просто принеси, я и тебе сделаю новый.",objectives={"Принесите зелье маны, уголь и сладкий нектар Талвашу де Кисселю в Стальгорн. Получите запасной фиал виденья Талваша."}]])
R(3376,"Сразить Остроклыка!",[[description="$N – я слыхала о тебе, $N. Возможно, именно тебе удастся то, что не удалось другим. $B$BМы, таурены, сделали это место своим домом, но это далось нам дорогой ценой. Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами. Я хочу, чтобы ты $Gпринес:принесла; мне голову их вождя! $B$BТы найдешь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда.",objectives={"Принесите голову вождя Остроклыка Терновой Мантии Храбрецу Перу Ветра на плато Красного Облака."}]])
R(3377,"Молитва Элуне",[[description="Мне нужна твоя помощь, $gсмертный:смертная;. Выслушай меня!",objectives={"Выслушайте Зимаэля."}]])
R(3378,"Молитва Элуне",[[description="Ты поможешь мне, $gсмертный:смертная;? Ты отыщешь молитву Элуне?$B$BКак я говорил, молитва выгравирована на золотой табличке, которая теперь, видимо, у одного из этих мерзких идолопоклонников. $B$BЕсли ты сможешь отыскать ее, отнеси табличку Астарии Ловцу Звезд в Дарнасс. Пусть я пришел к вере после того, как совершил много зла этому миру и его обитателям, моя молитва должна быть услышана. А на прощение своих грехов я не надеюсь...",objectives={"Найдите молитву Элуне и принесите ее Астарии Ловцу Звезд в Дарнасс."}]])
R(3379,"Мастер Тени",[[description="Пауки, которые водятся в Тлеющем ущелье, производят бесценный тенешелк. Как ты знаешь, тенешелк необходим для нашего ремесла. $B$BНе так давно в этих землях появилась шайка браконьеров, бессовестно убивающих пауков в погоне за сиюминутной прибылью. Твоя задача проста: найти их и прикончить. $B$BНачни поиски с северных пределов. $B$BЕсли потребуется помощь, обращайся к Пожару.",objectives={"Убейте банду похитителей тенешелка, хозяйничающую в Тлеющем ущелье. Нилит полагает, что их пятеро. Вернитесь к Нилит по выполнению задания."}]])
R(3380,"Затонувший храм",[[description="Этот мир полон беспокойных духов, $N. Среди них есть такие, которые оказались скованы в местах, в которых таится древнее зло, и были поражены скверной.$B$BСлыхал я о храме, сокрытом в глубинах болот – он был погружен туда силами, величие которых недоступно сознанию простого смертного.$B$BЕсли хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Он облазал многие развалины и останки древних поселений. Слыхал я, что недавно он отправился изучать развалины строений троллей в Танарисе.",objectives={"Найдите Марвона Клепальщика в Танарисе."}]])
R(3381,"Встреча с господином",[[description="О, $gюный:юная:r; $r $gпочтил:почтила; визитом Саната. О, это прекрасный день! Я так польщен! Благодарю тебя... $B$BНадеюсь, ты не столь $gсамонадеян:самонадеяна;, чтобы принять мой сарказм за чистую монету? Скажу прямо: ты мне не нравишься. Однако, речь сейчас не о том, хочу ли видеть тебя я, но о том, желает ли видеть тебя мой господин. $B$BПринеси мне пару перьев гиппогрифа для моих стрел, и я пропущу тебя к господину. Он принимает только тех, кто доказал, что на что-то годен.",objectives={"Принесите 2 неповрежденных пера гиппогрифа Санату Лим-Йо в в Азшару, если хотите говорить с его господином."}]])
R(3382,"На абордаж!",[[description="Мы плыли вдоль берега, в поисках места, где бросить якорь. Солнце зашло не более часа назад, и тут они на нас напали. Проклятые наги! $B$BНе знаю, что им было нужно, но они явно этого не нашли. Почему я в этом уверена? Потому что они вернулись! Я оставила пару своих людей охранять долину, чтобы они предупредили нас в случае атаки. $B$BМне жаль, что ты $gоказался втянутым:оказалась втянутой; в эту заварушку, но увы, ничего уже нельзя сделать. $B$BТы $gготов:готова; биться не на жизнь, а на смерть?",objectives={"Защитите капитана Ванессу Белтис, ее команду и пассажиров \"Покорителя Горизонтов\" от нападения наг. Капитан Ванесса Белтис должна выжить."}]])
R(3383,"<UNUSED>")
R(3384,"<UNUSED>")
R(3385,"Черный рынок",[[description="Они называют себя Черным рынком – шайка головорезов, которые готовы купить, продать и украсть что угодно, если цена будет подходящей.$B$BИ что еще хуже, $N, они устроили себе логово в Тлеющем ущелье. Искусный торговец Ковиц – их главарь. У него есть связи с местными дворфами клана Черного Железа.$B$BМы должны нанести по ним мощный удар и недвусмысленно дать понять, что здесь им не рады. Убей торговца Ковица и его прихвостня Лязгуна. Принеси мне сумку торговца.$B$BОтправляйся в Котел немедля!",objectives={"Убейте торговца Ковица и его прихвостня Лязгуна. Снимите с тела сумку и вернитесь к Нилит."}]])
R(3401,"<UNUSED>")
R(3402,"Черный рынок",[[description="Мне нужно, чтобы ты лично $gдонес:донесла; весть о кончине Ковиса Визглику в Прибамбасск. Он будет так рад, что непременно щедро наградит тебя.",objectives={"Поговорите с Визгликом в Прибамбасске."}]])
