R(9413,"<UNUSED>Crystal Flake Throat Lozenge")
R(9414,"<UNUSED>Infused Bandages")
R(9415,"Маршал Синяя Синестен",[[description="Ты новобранец маршала Синестена? Ну, конечно.$B$BЧего ты ждешь? Наши солдаты умирают там, в пустыне. Правда, тебе не терпится к ним присоединиться?$B$BИди, и смотри, не присохни к песку по пути.",objectives={"Поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора."}]])
R(9416,"Генерал Кирика",[[description="Должно быть, ты $gодин:одна; из новобранцев генерала Кирики. Пора тебе браться за дело. В пустыне тела очень быстро портятся.$B$BДворфы ежедневно получают подкрепление, а мы не должны им уступать. Полезные ископаемые Силитуса наши!$B$BГенерал тебя проинструктирует. Не мое дело – учить тебя. Мне приказали только найти тебя.",objectives={"Поговорите с генералом Кирикой в лагере Орды рядом с Ульем Регал."}]])
R(9419,"Истощение пустыни",[[description="Совсем недавно мы выяснили, что Орда добывает в Силитусе полезные ископаемые. Мы думали, что в таком климате не стоит держать много войск.$B$BК сожалению, выяснилось, насколько важны эти полезные ископаемые, и теперь мы тщетно пытаемся догнать Орду по масштабам добычи.$B$BЕсли ты хочешь мне помочь, ступай в пустыню и принеси оттуда силитист.",objectives={"Найдите и принесите силитист к экстрактору силитистов и поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора."}]])
R(9422,"Истощение пустыни",[[description="Мы давно начали добычу кристаллов пустыни Силитуса. Поначалу мы сталкивались лишь с опасностями, исходящими от местных жителей, песка, пыли и жары.$B$BТеперь же Альянс пронюхал, чем мы тут занимаемся, и началась гонка за добычей полезных ископаемых.$B$BУ меня каждая пара рук на счету, надеюсь, ты мне тоже поможешь.",objectives={"Найдите и принесите силитист к экстрактору силитистов и поговорите с генералом Кирикой в лагере Орды возле Улья Регал."}]])
